void xoagiua(node **head, int k){
    if(k < 1 || k > len(*head)) return;  // vi tri khong hop le
    if(k == 1){ xoadau(head); return; }  // k=1: khong co node k-1
    node *tmp = *head;
    for(int i = 1; i <= k - 1; i++)
        tmp = tmp->next;                 // toi dung node k
    tmp->prev->next = tmp->next;
    if(tmp->next != NULL)
        tmp->next->prev = tmp->prev;     // K+1 co ton tai
    free(tmp);
}
